-- Week 7: files, CSV data, and Pillow.
DO $$
DECLARE c uuid; m integer;
BEGIN
 SELECT id INTO c FROM public.courses WHERE slug='python-foundations';
 IF c IS NULL THEN RAISE EXCEPTION 'Python Foundations course must exist'; END IF;
 INSERT INTO public.modules(course_id,month_number,title,tagline,description,capstone_title,is_free,order_index,status)
 VALUES(c,7,'Files and Structured Data','Week 7 · Sessions 1–5','Read and write saved text, work with CSV tables, and learn where image libraries fit.','A Clean Copy of a Class List',false,7,'published')
 ON CONFLICT(course_id,month_number,order_index) DO UPDATE SET title=EXCLUDED.title,tagline=EXCLUDED.tagline,description=EXCLUDED.description,capstone_title=EXCLUDED.capstone_title,is_free=EXCLUDED.is_free,status=EXCLUDED.status
 RETURNING id INTO m;
 WITH d(n,title,analogy,body,starter,q,opts,ans,why) AS (VALUES
 (1,'Open and Read a Text File','A saved file is like a notebook that can be opened again.','## Goal\nRead text saved in a file.\n\n## Plain explanation\n`open("names.txt", "r")` asks Python to open a file in read mode. The `with` statement makes sure Python closes it after the indented work is finished. `file.read()` returns the contents as text. The file must exist where Python is looking; a browser editor may not have access to your computer folders.\n\n## Example\n```python\nwith open("names.txt", "r") as file:\n    names = file.read()\nprint(names)\n```\n\n## Try it\nRead a small provided text file and print its contents.','with open("names.txt", "r") as file:\n    contents = file.read()\n\nprint(contents)','Why use `with open(...)`?','["It closes the file safely after the block", "It creates a picture", "It changes text into a number"]'::jsonb,0,'The with block manages the open file and closes it when the block ends.'),
 (2,'Write or Add Text to a File','Choose whether to replace a notebook page or add a new line.','## Goal\nSave text in a file and understand the difference between write and append modes.\n\n## Plain explanation\nWrite mode `"w"` creates a file or replaces its old contents. Append mode `"a"` adds new text at the end. Choose carefully because write mode can erase earlier contents. `write()` does not add a new line automatically, so include `\\n` when needed.\n\n## Example\n```python\nwith open("notes.txt", "a") as file:\n    file.write("Practiced Python\\n")\n```\n\n## Try it\nWrite one line to a new file, then change the mode to append and add another line.','with open("notes.txt", "w") as file:\n    file.write("First note\\n")','Which mode adds text without replacing existing contents?','["a", "w", "r"]'::jsonb,0,'Append mode, written as a, adds new content at the end.'),
 (3,'Read Rows from a CSV Table','A CSV resembles a small spreadsheet saved as plain text.','## Goal\nRead rows and headings from a CSV file.\n\n## Plain explanation\nCSV means comma-separated values. A row stores related fields, and the first row often names the columns. Python’s `csv.DictReader` uses those headings so a row can be read with names such as `row["name"]`, instead of remembering positions. Use the `csv` library that comes with Python.\n\n## Example\n```python\nimport csv\nwith open("students.csv", newline="") as file:\n    for row in csv.DictReader(file):\n        print(row["name"])\n```\n\n## Try it\nRead the `name` column from a supplied two-row CSV.','import csv\n\nwith open("students.csv", newline="") as file:\n    for row in csv.DictReader(file):\n        print(row["name"])','What does DictReader use to label each field?','["The header row", "The file extension only", "The last row"]'::jsonb,0,'DictReader reads the header row and uses its column names as keys.'),
 (4,'Transform CSV Data into a New File','Keep the original list safe and create a cleaned copy.','## Goal\nRead structured rows, change them, and save the result separately.\n\n## Plain explanation\nA data conversion program reads one file and writes a second file. Keeping the original protects the source if a mistake occurs. `csv.DictWriter` writes rows using named columns. Check that the input file and expected headings exist, and explain errors clearly.\n\n## Example\n```python\nimport csv\nwith open("input.csv", newline="") as source:\n    rows = list(csv.DictReader(source))\nwith open("output.csv", "w", newline="") as target:\n    writer = csv.DictWriter(target, fieldnames=["first", "last"])\n    writer.writeheader()\n    writer.writerows(rows)\n```\n\n## Supplied practice\nScourgify rearranges name fields into a new CSV. Pizza Py reads CSV rows and formats a table.','import csv\n\n# Read the source rows, then write converted rows to a separate file.','Why save transformed rows to a new file?','["To keep the original data unchanged", "CSV files cannot be read twice", "Python requires every file to be empty"]'::jsonb,0,'A separate output file protects the original input while you check the transformed result.'),
 (5,'Use Pillow to Edit an Image','An image library provides ready-made tools for picture files.','## Goal\nUnderstand how a library such as Pillow opens and saves images.\n\n## Plain explanation\nPillow is an add-on Python package for image work. A local project can install it in a terminal with `python -m pip install pillow`; this is a terminal command, not Python code to type in the editor. The program needs an image file it can access. Open an image, make a simple edit, then save a copy with a new name.\n\n## Example\n```python\nfrom PIL import Image\nimage = Image.open("photo.png")\nimage.save("copy.png")\n```\n\n## Supplied practice\nCS50 P-Shirt combines a supplied shirt overlay and photo. Use a local environment with Pillow and the image files; the browser editor may not provide either.','from PIL import Image\nimage = Image.open("photo.png")\nimage.save("copy.png")','Where should `python -m pip install pillow` be run?','["In a terminal", "Inside an image filename", "As a Python variable"]'::jsonb,0,'The pip install command is typed in a terminal to install the package into the Python environment.')
 ), ins AS (
 INSERT INTO public.sessions(module_id,session_number,title,analogy_physical,content_markdown,starter_code,hints,xp_reward,order_index,duration_minutes,quick_check)
 SELECT m,n,title,analogy,replace(replace(replace(body,'file.write("Practiced Python'||chr(92)||'n")','file.write("Practiced Python")'),'Pizza Py reads CSV rows and formats a table.','Pizza Py reads a CSV using a command line filename and formats a table with the external tabulate package.'),chr(92)||'n',chr(10)),replace(starter,chr(92)||'n',chr(10)),'["Read the example one line at a time.","Check the file name and mode.","Try a tiny sample file first."]'::jsonb,50,n,15,jsonb_build_object('question',q,'options',opts) FROM d
 ON CONFLICT(module_id,session_number) DO UPDATE SET title=EXCLUDED.title,analogy_physical=EXCLUDED.analogy_physical,content_markdown=EXCLUDED.content_markdown,starter_code=EXCLUDED.starter_code,hints=EXCLUDED.hints,xp_reward=EXCLUDED.xp_reward,order_index=EXCLUDED.order_index,duration_minutes=EXCLUDED.duration_minutes,quick_check=EXCLUDED.quick_check RETURNING id,session_number
 ) INSERT INTO private.session_quick_check_answers(session_id,correct_option,explanation) SELECT ins.id,d.ans,d.why FROM ins JOIN d ON d.n=ins.session_number ON CONFLICT(session_id) DO UPDATE SET correct_option=EXCLUDED.correct_option,explanation=EXCLUDED.explanation;
END $$;
